node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Search for the product PROD-2028EE or 'Magnetic Wireless Charging Stand'
let rows = db.prepare(\"SELECT * FROM products WHERE product_id LIKE '%2028%' OR name LIKE '%Magnetic%' OR name LIKE '%Charging%' OR name LIKE '%Wireless%Charging%'\").all();
console.log('Products search:', JSON.stringify(rows, null, 2));

// Check columns
const cols = db.prepare(\"PRAGMA table_info(products)\").all();
console.log('Products columns:', JSON.stringify(cols.map(c => c.name)));
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Check if 'Maya Chen' is a user/contact or a device
let users = db.prepare(\"SELECT * FROM users WHERE name LIKE '%Maya%' OR name LIKE '%Chen%'\").all();
console.log('Users search:', JSON.stringify(users, null, 2));

// Check contacts
let contacts = db.prepare(\"SELECT * FROM ts_contacts WHERE name LIKE '%Maya%' OR name LIKE '%Chen%'\").all();
console.log('Contacts search:', JSON.stringify(contacts, null, 2));

// Check all user columns
const userCols = db.prepare(\"PRAGMA table_info(users)\").all();
console.log('User columns:', JSON.stringify(userCols.map(c => c.name)));
"
